import html

def esc(value): return html.escape(str(value), quote=True)
STYLE = '''
:root{color-scheme:light;--ink:#172a35;--muted:#687b86;--line:#dde5e8;--accent:#087f75;--bg:#f4f7f8;--surface:#fff;--field-border:#bdcdd3;--button-bg:#087f75;--button-hover:#06685f;--notice:#e5f4ef;--notice-border:#b3dacc;--error:#fff0ed;--error-border:#ecc6bb;--subtle:#e7f2f0}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 system-ui,sans-serif}a{color:var(--accent);text-decoration:none}a:hover{text-decoration:underline}header{background:var(--surface);border-bottom:1px solid var(--line)}.bar{max-width:1200px;margin:auto;padding:20px 28px;display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{color:var(--ink);font-size:23px;font-weight:850;letter-spacing:-1px}.brand b{background:var(--button-bg);color:white;padding:5px 9px;border-radius:9px;margin-right:9px}nav{display:flex;align-items:center;gap:24px}main{max-width:1200px;margin:44px auto;padding:0 28px}h1{font-size:clamp(30px,4vw,46px);line-height:1.15;letter-spacing:-1.5px;margin:12px 0 18px}h2{font-size:21px;line-height:1.4;letter-spacing:-.4px}.eyebrow,.tag{font-size:12px;text-transform:uppercase;letter-spacing:1.5px;font-weight:750;color:var(--accent)}.intro{color:var(--muted);max-width:650px}.filters{display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:14px;background:var(--surface);border:1px solid var(--line);padding:22px;border-radius:16px;margin:30px 0}label{display:block;font-size:13px;font-weight:650}input,select{font:inherit;width:100%;padding:11px 13px;border:1px solid var(--field-border);border-radius:8px;background:var(--surface);color:var(--ink);margin-top:6px}button,.button{font:inherit;font-weight:650;background:var(--button-bg);color:white;border:0;padding:12px 20px;border-radius:8px;cursor:pointer;display:inline-block}button:hover,.button:hover{background:var(--button-hover);text-decoration:none}.filters button{align-self:end}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}article{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:26px;display:flex;flex-direction:column}article h2 a{color:var(--ink)}article p{color:var(--muted)}.meta,small{font-size:13px;color:var(--muted)}.cardfoot{margin-top:auto;padding-top:18px;border-top:1px solid var(--line);display:flex;justify-content:space-between;gap:10px}.results{display:flex;justify-content:space-between;margin:24px 0}.empty{grid-column:1/-1;text-align:center;padding:55px;border:1px dashed var(--field-border);border-radius:14px}.auth{max-width:460px;margin:50px auto;background:var(--surface);border:1px solid var(--line);border-radius:18px;padding:32px}.auth h1{font-size:30px}.auth label{margin:18px 0}.auth button{width:100%;margin-top:8px}.notice{background:var(--notice);border:1px solid var(--notice-border);padding:14px;border-radius:9px}.error{background:var(--error);border-color:var(--error-border)}.reading{max-width:800px;margin:auto}.reading h1{font-size:36px}.reading p{white-space:pre-line}footer{max-width:1200px;margin:70px auto 0;padding:24px 28px;border-top:1px solid var(--line);color:var(--muted);font-size:13px}.logout{display:inline}.logout button{padding:6px 10px;font-size:13px;background:var(--subtle);color:var(--accent)}:focus-visible{outline:3px solid #e6ad47;outline-offset:3px}@media(max-width:900px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.filters{grid-template-columns:1fr 1fr}}@media(max-width:600px){.bar{padding:16px;align-items:flex-start}nav{gap:12px;flex-wrap:wrap;justify-content:flex-end;font-size:13px}main{padding:0 16px;margin-top:28px}.cards,.filters{grid-template-columns:1fr}.auth{padding:24px}.brand{white-space:nowrap;font-size:20px}.reading h1{font-size:29px}}
:root[data-theme="dark"]{color-scheme:dark;--ink:#e5edf3;--muted:#a6b6c3;--line:#334452;--accent:#6edbca;--bg:#101820;--surface:#192630;--field-border:#526775;--button-bg:#087f75;--button-hover:#06685f;--notice:#173d35;--notice-border:#397868;--error:#442b2b;--error-border:#9b5a54;--subtle:#233c3b;}
@media(prefers-color-scheme:dark){:root:not([data-theme="light"]){color-scheme:dark;--ink:#e5edf3;--muted:#a6b6c3;--line:#334452;--accent:#6edbca;--bg:#101820;--surface:#192630;--field-border:#526775;--button-bg:#087f75;--button-hover:#06685f;--notice:#173d35;--notice-border:#397868;--error:#442b2b;--error-border:#9b5a54;--subtle:#233c3b;}}
.theme-toggle{background:var(--subtle);color:var(--ink);border:1px solid var(--line);padding:8px 12px;white-space:nowrap;font-size:13px}.theme-toggle:hover{background:var(--surface)}.theme-toggle[hidden]{display:none}
'''
def page(content,title='News',user=None,csrf=''):
    account = f'<span class="meta">{esc(user["email"])}</span><form class="logout" action="/logout" method="post"><input type="hidden" name="csrf" value="{esc(csrf)}"><button>Abmelden</button></form>' if user else '<a href="/login">Anmelden</a><a class="button" href="/register">Konto erstellen</a>'
    return f'<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><script src="/theme.js"></script><title>{esc(title)} · AG News</title><style>{STYLE}</style></head><body><header><div class="bar"><a class="brand" href="/"><b>AG</b>News</a><nav><a href="/">Übersicht</a><a href="/rss.xml">RSS ↗</a>{account}<button id="theme-toggle" class="theme-toggle" type="button" aria-label="Dunklen Modus aktivieren" aria-pressed="false" hidden>☾ Dunkel</button></nav></div></header><main>{content}</main><footer>AG News · Dein Überblick über IT & Sicherheit<br>Automatischer Quellenüberblick. Meldungen anhand der Originalquelle prüfen. Impressum und Datenschutz vor öffentlicher Freischaltung ergänzen.</footer></body></html>'
